insert='''function accItems(){return ['إحرام','جوارب','كبك','قلم','سبحة','عطر']}function perfumeSavedFeedTypes(){let sec=app.sections.find(x=>x.name==='الإكسسوارات والجوارب');if(!sec)return[];let out=[];[...shortagesData,...accDraft].forEach(x=>{let label=String(x.size||x.label||'');let m=label.match(/^عطر — (.+?) — المطلوب /);if(m&&m[1]&&!out.includes(m[1]))out.push(m[1])});return out.sort((a,b)=>a.localeCompare(b,'ar'))}function renderAccControls(){$('accItemChoices').innerHTML=accItems().map(v=>`<button class="mini ${accItem===v?'on':''}" onclick="selectAccItem('${v}',this)">${esc(v)}</button>`).join('');$('accSocksArea').classList.toggle('hidden',accItem!=='جوارب');document.querySelectorAll('#accSocksChoices .mini').forEach(b=>b.classList.toggle('on',b.dataset.value===accSocksType));$('accPerfumeArea').classList.toggle('hidden',accItem!=='عطر');let sel=$('perfumeFeedTypeSelect');if(accItem==='عطر'){let current=sel.value,types=perfumeSavedFeedTypes();sel.innerHTML='<option value="">اختر نوع التغذية</option>'+types.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')+'<option value="__new__">إضافة نوع تغذية جديد</option>';if(types.includes(current)||current==='__new__')sel.value=current;$('perfumeNewFeedBox').classList.toggle('hidden',sel.value!=='__new__')}updateAccSummary()}function selectAccItem(v,b){accItem=v;accSocksType='';if($('perfumeFeedTypeSelect'))$('perfumeFeedTypeSelect').value='';if($('perfumeNewFeedType'))$('perfumeNewFeedType').value='';if($('perfumeWanted'))$('perfumeWanted').value='';renderAccControls()}function selectAccSocksType(v,b){accSocksType=v;renderAccControls()}function perfumeFeedTypeChanged(){$('perfumeNewFeedBox').classList.toggle('hidden',$('perfumeFeedTypeSelect').value!=='__new__');updateAccSummary()}function accCurrentLabel(){if(!accItem)return'';if(accItem==='جوارب')return accSocksType?`جوارب — ${accSocksType}`:'';if(accItem==='عطر'){let raw=$('perfumeFeedTypeSelect')?.value||'',feed=raw==='__new__'?$('perfumeNewFeedType')?.value.trim():raw,wanted=$('perfumeWanted')?.value.trim();return feed&&wanted?`عطر — ${feed} — المطلوب ${wanted}`:''}return accItem}function updateAccSummary(){let label=accCurrentLabel();$('accSummary').innerHTML=label?`المحدد: <b>${esc(label)}</b>`:(accItem==='جوارب'?'اختر نوع الجوارب.':accItem==='عطر'?'اختر نوع التغذية واكتب المطلوب.':accItem?'جاهز لتسجيل الكميات.':'اختر الصنف.');$('accSelected').classList.toggle('hidden',!label);if(label){$('accCurrent').value='0';$('accRequested').value='0';$('accLost').value='0'}}function addAccDraft(){try{let label=accCurrentLabel();if(!label){if(accItem==='عطر')throw Error('اختر نوع التغذية واكتب المطلوب');throw Error('أكمل اختيار الصنف')}let section=$('shortSection').value,key=label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)throw Error(`هذا الصنف له طلب تغذية قائم بالفعل منذ ${dup.ordered_date||'—'}`);if(accDraft.some(x=>x.label.trim().toLowerCase()===key))throw Error('هذا الصنف مضاف بالفعل في الطلب الحالي');let current=Number($('accCurrent').value||0),requested=Number($('accRequested').value||0),lost=Number($('accLost').value||0);if([current,requested,lost].some(x=>Number.isNaN(x)||x<0))throw Error('أدخل الكميات بشكل صحيح');accDraft.push({label,current_qty:current,requested_qty:requested,lost_opportunities:lost});renderAccDraft();if(accItem==='عطر'){let sel=$('perfumeFeedTypeSelect'),newType=$('perfumeNewFeedType').value.trim();if(sel.value==='__new__'&&newType){renderAccControls();sel.value=newType}$('perfumeWanted').value='';$('perfumeNewFeedType').value=''}$('accCurrent').value='0';$('accRequested').value='0';$('accLost').value='0';updateAccSummary()}catch(e){alert(e.message)}}function removeAccDraft(i){accDraft.splice(i,1);renderAccDraft();if(accItem==='عطر')renderAccControls()}function renderAccDraft(){$('accDraftList').innerHTML=accDraft.length?accDraft.map((x,i)=>`<div class="task"><b>${esc(x.label)}</b><div class="mut" style="margin-top:6px">الموجود: ${x.current_qty} | المطلوب للتغذية: ${x.requested_qty} | الفرص الضائعة: ${x.lost_opportunities}</div><div style="margin-top:8px"><button class="mini" style="color:#c83b3b;border-color:#efb4b4" onclick="removeAccDraft(${i})">حذف</button></div></div>`).join(''):'<p class="mut">لم تتم إضافة أصناف بعد.</p>'}'''
