save='''async function saveAccShortages(){try{let section=$('shortSection').value,sec=app.sections.find(s=>s.id===section);if(sec?.name!=='الإكسسوارات والجوارب')throw Error('اختر قسم الإكسسوارات والجوارب');if(!accDraft.length)throw Error('أضف صنفًا واحدًا على الأقل');for(const row of accDraft){let key=row.label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)throw Error(`يوجد طلب قائم للصنف ${row.label} منذ ${dup.ordered_date||'—'}`)}await api('shortage-save',{method:'POST',body:{section_id:section,reporter_employee_id:$('shortReporter').value,rows:accDraft.map(x=>({size:x.label,current_qty:x.current_qty,requested_qty:x.requested_qty,lost_opportunities:x.lost_opportunities}))}});accDraft=[];accItem='';accSocksType='';shortagesData=await api('shortages');renderAccControls();renderAccDraft();renderShortages();alert('تم حفظ نواقص الإكسسوارات والجوارب')}catch(e){alert(e.message)}}'''
